# longest stop-free stretch per frame (six frames) - i.e. max coding run
def longest_stopfree(s):
    res=[]
    for f in range(3):
        i=f; cur=0; s0=f
        runstart=f
        for j in range(f,len(s)-2,3):
            c=s[j:j+3]
            if c in stops:
                if j-runstart>0:
                    res.append((runstart+1,j+3-3, j-runstart, ) )  # placeholder
                runstart=j+3
        # handle tail
        if runstart<len(s)-2:
            end=runstart+ ((len(s)-2-runstart)//3)*3
            res.append((runstart+1,end,end-runstart))
    return res

def runs(s):
    out=[]
    for f in range(3):
        runstart=f
        for j in range(f,len(s)-2,3):
            if s[j:j+3] in stops:
                if j>runstart:
                    out.append((runstart,j))  # 0-based half-open in frame coords
                runstart=j+3
        if runstart<len(s)-2:
            end=runstart+((len(s)-2-runstart)//3)*3
            out.append((runstart,end))
    return out

